function validate([points, s]) {
  if (points.length < 1 || points.length > 100000) return 'points needs 1 to 10^5 entries.';
  if (s.length !== points.length) return 's needs exactly one tag per point.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase letters.';
  const used = new Set();
  for (const point of points) {
    if (point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => v < -1000000000 || v > 1000000000)) return 'Coordinates are between -10^9 and 10^9.';
    const key = point[0] + ',' + point[1];
    if (used.has(key)) return 'No two points may share coordinates.';
    used.add(key);
  }
  return null;
}

