function maxPointsInsideSquare(points, s) {
  const order = points.map(([x, y], i) => ({ dist: Math.max(Math.abs(x), Math.abs(y)), tag: s[i] }));
  order.sort((a, b) => a.dist - b.dist);
  const seen = new Set();
  let inside = 0;

  while (inside < order.length) {
    const dist = order[inside].dist;
    let next = inside;
    while (next < order.length && order[next].dist === dist) {
      const tag = order[next].tag;
      if (seen.has(tag)) {
        return inside;
      }
      seen.add(tag);
      next++;
    }
    inside = next;
  }
  return inside;
}

