function maxPointsInsideSquare(points, s) {
  // Try half side 0 and every point's distance as the square's half side; keep the best square whose tags all differ.
  let best = 0;
  const halves = [0, ...points.map(([x, y]) => Math.max(Math.abs(x), Math.abs(y)))];
  for (const half of halves) {
    const tags = [];
    for (let i = 0; i < points.length; i++) {
      if (Math.abs(points[i][0]) <= half && Math.abs(points[i][1]) <= half) tags.push(s[i]);
    }
    if (new Set(tags).size === tags.length) best = Math.max(best, tags.length);
  }
  return best;
}

