function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const used = new Set();
  const points = [];
  let s = '';
  const add = (x, y, tag) => {
    const key = x + ',' + y;
    if (used.has(key)) return;
    used.add(key);
    points.push([x, y]);
    s += tag;
  };
  if (size === 'small') {
    // A tiny grid and few letters make equal distances and repeated tags common.
    const span = 1 + pick(4);
    const n = 1 + pick(Math.min(10, (2 * span + 1) ** 2));
    const letters = 1 + pick(5);
    const scale = rand() < 0.2 ? 250000000 : 1;
    while (points.length < n) add((pick(2 * span + 1) - span) * scale, (pick(2 * span + 1) - span) * scale, alphabet[pick(letters)]);
    return [points, s];
  }
  // Large: up to 26 points with different tags near the origin, then many farther points with random tags.
  const n = 1500 + pick(501);
  const near = pick(27);
  const tags = [...alphabet];
  for (let i = tags.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [tags[i], tags[j]] = [tags[j], tags[i]];
  }
  for (let i = 0; i < near; i++) {
    const d = i + 1;
    const t = pick(2 * d + 1) - d;
    const side = pick(4);
    const [x, y] = side === 0 ? [d, t] : side === 1 ? [-d, t] : side === 2 ? [t, d] : [t, -d];
    add(x, y, tags[i]);
  }
  const limit = rand() < 0.5 ? 1000000000 : 5000;
  while (points.length < n) {
    const x = pick(2 * limit + 1) - limit;
    const y = pick(2 * limit + 1) - limit;
    if (Math.max(Math.abs(x), Math.abs(y)) > near + 1) add(x, y, alphabet[pick(26)]);
  }
  return [points, s];
}
